static partial class App {
 static int SizeIntegration(string[] args){string root=Path.GetFullPath(args[1]);Directory.CreateDirectory(root);ErrorLog.DirectoryPath=Path.Combine(root,"logs");var store=new Store(Path.Combine(root,"data"));var baseline=store.Capture();store.Write("emergency-baseline.json",baseline);var log=new List<string>();var errors=new List<Exception>();Theme.ErrorSink=errors.Add;
  try{var imported=store.Import(new[]{args[2]},48,0,0);store.Pref.Hotkeys=false;using(var form=new MainForm(store)){form.Show();form.TestSize(imported,32,true);WaitSize(form);Assert(store.Pref.Active==imported.Id,"imported applied");CheckSystemSize(imported,32);Assert(store.Capture().Values.First(p=>p.Name=="Arrow").Value==imported.DisplayRoles["Arrow"],"registry uses resized imported ANI");form.TestSizeCombo(imported,"96 px");WaitSize(form);var actual=store.Capture().Values.First(p=>p.Name=="Arrow").Value;Assert(CursorFrames(File.ReadAllBytes(actual))[0][6]==96,"size combo immediately updates active native cursor");CheckSystemSize(imported,96);log.Add("PASS: real UI size selection changes an active imported ANI/CUR scheme from 32 to 96 px; registry points at resized files.");
   form.TestSizeCombo(imported,"跟随全局 (48 px)");WaitSize(form);form.TestGlobalSize(64);WaitSize(form);actual=store.Capture().Values.First(p=>p.Name=="Arrow").Value;Assert(store.Pref.Size==64&&CursorFrames(File.ReadAllBytes(actual))[0][6]==64,"global settings update active imported skin");CheckSystemSize(imported,64);log.Add("PASS: actual settings dialog changes global size and automatically updates the active imported scheme.");
   form.TestSize(store.Pref.Skins[22],96,true);WaitSize(form);Assert(store.Pref.Active==store.Pref.Skins[22].Id,"builtin applied at 96");CheckSystemSize(store.Pref.Skins[22],96);form.TestSizeCombo(store.Pref.Skins[22],"32 px");WaitSize(form);actual=store.Capture().Values.First(p=>p.Name=="Arrow").Value;Assert(CursorFrames(File.ReadAllBytes(actual))[0][6]==32,"builtin size selector active");CheckSystemSize(store.Pref.Skins[22],32);log.Add("PASS: active animated builtin skin changes from 96 to 32 px through its real size control.");
   foreach(var tested in new[]{store.Pref.Skins[0],store.Pref.Skins[4],store.Pref.Skins[22],imported})foreach(int n in CursorSizing.Sizes){form.TestSize(tested,n,true);WaitSize(form);CheckSystemSize(tested,n);using(var bitmap=Native.DrawSystemCursor("Arrow",0))bitmap.Save(Path.Combine(root,"actual-"+tested.Id+"-"+n+".png"));}log.Add("PASS: GetIconInfo reads actual shared Windows cursors at all four sizes for static builtin, animated builtin, fun animation and imported Sweezy; all available roles and hotspots match preview and native-size handles.");CheckAnimation(Math.Min(8,CursorFrames(File.ReadAllBytes(imported.DisplayRoles["Arrow"])).Count));log.Add("PASS: actual imported Sweezy system cursor retains its animation frames after resizing.");form.TestSize(store.Pref.Skins[22],96,true);WaitSize(form);CheckAnimation();form.TestSize(imported,96,true);WaitSize(form);log.Add("PASS: actual system animated cursor produces different frames after SetSystemCursor.");form.TestSizeCombo(store.Pref.Skins[22],"96 px");WaitSize(form);form.TestGlobalSize(48);WaitSize(form);Assert(store.Pref.Skins.All(s=>s.SizeOverride==0),"global-all resets per-skin overrides");CheckSystemSize(imported,48);log.Add("PASS: global-all checkbox resets independent sizes and updates actual active cursor.");store.Apply(store.Pref.Skins[0]);store.Restore(false);CheckSystemSize(imported,48);log.Add("PASS: undo restores actual requested size, not only file paths.");form.TestSize(store.Pref.Skins[23],96,true);form.ExitApplication();WaitSize(form);AssertDefault(store);Assert(errors.Count==0,"no size apply errors");log.Add("PASS: exiting during generation cancels pending application and leaves Windows default cursors.");}
  }finally{Theme.ErrorSink=null;store.SetSnapshot(baseline);log.Add("FINALLY: desktop cursor scheme restored exactly to the pre-test snapshot.");File.WriteAllLines(Path.Combine(root,"size-integration-results.txt"),log,Encoding.UTF8);}return 0;
 }
 static void CheckAnimation(int steps=8){var role="Arrow";var values=new HashSet<string>();for(uint f=0;f<(uint)steps;f++){using(var bitmap=Native.DrawSystemCursor(role,f))using(var stream=new MemoryStream()){bitmap.Save(stream,System.Drawing.Imaging.ImageFormat.Png);values.Add(Convert.ToBase64String(stream.ToArray()));}}Assert(values.Count>1,"system ANI frames remain animated");}
 static void CheckSystemSize(Skin s,int expected){foreach(var pair in s.DisplayRoles){var actual=Native.SystemCursorSize(pair.Key);Assert(Math.Max(actual.Width,actual.Height)==expected,"actual Windows shared "+pair.Key+" size should be "+expected+", got "+actual);using(var preview=new Preview{Playground=true}){preview.LoadFile(pair.Value);Assert(preview.NativeSize==actual,"preview and actual system cursor sizes match");var source=Native.LoadExactCursor(pair.Value);try{int index=Array.IndexOf(Store.Roles,pair.Key);var sys=Native.LoadCursor(IntPtr.Zero,new IntPtr(Native.CursorIds[index]));Assert(Native.CursorHotspot(source)==Native.CursorHotspot(sys),"actual system hotspot matches file");}finally{Native.DestroyCursor(source);}}}}
 internal static void WaitSize(MainForm form){var time=Stopwatch.StartNew();while(!form.SizeTask.IsCompleted&&time.ElapsedMilliseconds<30000){Application.DoEvents();Thread.Sleep(5);}Assert(form.SizeTask.IsCompleted,"background sizing completes within 30 seconds");form.SizeTask.GetAwaiter().GetResult();}
 static int SizeTest(string[] args){string root=Path.GetFullPath(args[1]);Directory.CreateDirectory(root);ErrorLog.DirectoryPath=Path.Combine(root,"logs");var log=new List<string>();var store=new Store(Path.Combine(root,"data"),false);var token=CancellationToken.None;
  var imported=store.Import(new[]{args[2]},48,0,0);var originals=imported.Roles.ToDictionary(p=>p.Key,p=>File.ReadAllBytes(p.Value));
  foreach(int size in CursorSizing.Sizes){var resized=store.PrepareSize(imported,size,token);foreach(var pair in resized){Native.Validate(pair.Value);var originalFrames=CursorFrames(originals[pair.Key]);var newFrames=CursorFrames(File.ReadAllBytes(pair.Value));Assert(newFrames.Count==originalFrames.Count,"Sweezy animation frame count retained");for(int i=0;i<newFrames.Count;i++){byte[] a=originalFrames[i],b=newFrames[i];int entry=BestEntry(a,size);int ow=a[entry]==0?256:a[entry],oh=a[entry+1]==0?256:a[entry+1],nw=b[6]==0?256:b[6],nh=b[7]==0?256:b[7];Assert(Math.Max(nw,nh)==size,"Sweezy output size");if(BitConverter.ToUInt16(a,2)==2){Assert(BitConverter.ToUInt16(b,10)==Math.Min(nw-1,(int)Math.Round(BitConverter.ToUInt16(a,entry+4)*(double)nw/ow)),"scaled hotspot X");Assert(BitConverter.ToUInt16(b,12)==Math.Min(nh-1,(int)Math.Round(BitConverter.ToUInt16(a,entry+6)*(double)nh/oh)),"scaled hotspot Y");}}}foreach(var pair in originals)Assert(pair.Value.SequenceEqual(File.ReadAllBytes(imported.Roles[pair.Key])),"source bytes unchanged");}
  log.Add("PASS: real Sweezy ANI + CUR resize at 32/48/64/96 px, native Windows loading, frame counts and proportional hotspots; original files unchanged.");
  var frames=new List<byte[]>();using(var image=new Bitmap(40,20)){using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);g.FillRectangle(Brushes.Coral,3,4,24,10);}frames.Add(Art.Cur(image,8,5));frames.Add(Art.Cur(image,8,5));}byte[] animation=Art.Ani(frames,new[]{3,11,5});
  // Add a repeated/reordered sequence and change nSteps to exercise real ANI timing.
  Buffer.BlockCopy(BitConverter.GetBytes(3),0,animation,28,4);Buffer.BlockCopy(BitConverter.GetBytes(3),0,animation,52,4);
  using(var ms=new MemoryStream()){ms.Write(animation,0,animation.Length);using(var w=new BinaryWriter(ms)){w.Write(Encoding.ASCII.GetBytes("seq "));w.Write(12);w.Write(1);w.Write(0);w.Write(1);w.Flush();animation=ms.ToArray();}}Buffer.BlockCopy(BitConverter.GetBytes(animation.Length-8),0,animation,4,4);
  var scaledAnimation=CursorSizing.Resize(animation,96,token);foreach(string id in new[]{"rate","seq "}){int a=FindChunk(animation,id),b=FindChunk(scaledAnimation,id);int length=BitConverter.ToInt32(animation,a+4);Assert(animation.Skip(a).Take(length+8).SequenceEqual(scaledAnimation.Skip(b).Take(length+8)),"ANI sequence/rate preserved");}var scaledFrame=CursorFrames(scaledAnimation)[0];Assert(scaledFrame[6]==96&&scaledFrame[7]==48,"non-square aspect ratio retained");Assert(BitConverter.ToUInt16(scaledFrame,10)==19&&BitConverter.ToUInt16(scaledFrame,12)==12,"non-square hotspot");string aniPath=Path.Combine(root,"sequence.ani");File.WriteAllBytes(aniPath,scaledAnimation);Native.Validate(aniPath);log.Add("PASS: non-square images retain aspect ratio; ANI per-step rates, repeated sequence, frame order and step count survive resizing.");
  imported.SizeOverride=-1;Assert(store.PrepareSize(imported,-1,token)["Arrow"]==imported.Roles["Arrow"],"original size mode");imported.SizeOverride=64;store.Save();var reloaded=new Store(store.Root,false);Assert(reloaded.Pref.Skins.First(s=>s.Id==imported.Id).SizeOverride==64,"per-skin size persists");log.Add("PASS: original-size mode, per-skin size persistence and size cache reuse.");
  var damaged=store.PrepareSize(imported,64,token);File.WriteAllText(damaged["Arrow"],"interrupted cache");Native.Validate(store.PrepareSize(imported,64,token)["Arrow"]);var builtinCache=store.PrepareSize(store.Pref.Skins[4],64,token);File.WriteAllText(builtinCache["Arrow"],"interrupted cache");Native.Validate(store.PrepareSize(store.Pref.Skins[4],64,token)["Arrow"]);log.Add("PASS: interrupted/corrupt imported and builtin size caches regenerate automatically.");
  bool canceled=false;using(var cts=new CancellationTokenSource()){cts.Cancel();try{store.PrepareSize(imported,96,cts.Token);}catch(OperationCanceledException){canceled=true;}}Assert(canceled,"canceled worker exits");
  var errors=new List<Exception>();Theme.ErrorSink=e=>errors.Add(e);store.Pref.Hotkeys=false;using(var form=new MainForm(store)){form.Show();int ticks=0;long maxGap=0,last=0;var watch=Stopwatch.StartNew();using(var timer=new System.Windows.Forms.Timer{Interval=15}){timer.Tick+=(o,e)=>{long now=watch.ElapsedMilliseconds;if(last>0)maxGap=Math.Max(maxGap,now-last);last=now;ticks++;};timer.Start();form.TestSize(store.Pref.Skins[22],96,false);WaitSize(form);Assert(ticks>1&&maxGap<1500,"UI pumps while cold animated skin generates");log.Add("PASS: cold 96 px animated full scheme prepared in background with "+ticks+" UI timer ticks; maximum message gap "+maxGap+" ms.");form.TestSize(store.Pref.Skins[22],32,false);form.TestSize(store.Pref.Skins[22],64,false);WaitSize(form);Assert(store.Pref.Skins[22].DisplayRoles["Arrow"].Contains("64"),"latest request wins");form.TestSize(imported,96,false);WaitSize(form);Assert(imported.DisplayRoles["Arrow"].Contains("96"),"imported UI preview resized");form.TestSize(store.Pref.Skins[23],96,false);var pending=form.SizeTask;form.ExitApplication();var deadline=DateTime.Now.AddSeconds(10);while(!pending.IsCompleted&&DateTime.Now<deadline){Application.DoEvents();Thread.Sleep(5);}Assert(form.IsDisposed&&pending.IsCompleted,"exit cancels size work");}File.WriteAllLines(Path.Combine(root,"ui-errors.txt"),errors.Select(e=>e.ToString()));Assert(errors.Count==0,"no UI sizing errors");}Theme.ErrorSink=null;log.Add("PASS: rapid size requests use newest selection; imported preview scales; exit cancels pending work without applying after exit.");File.WriteAllLines(Path.Combine(root,"size-results.txt"),log,Encoding.UTF8);return 0;
 }
 static int BestEntry(byte[] b,int size){int best=6;double score=double.MaxValue;for(int i=0;i<BitConverter.ToUInt16(b,4);i++){int p=6+16*i;double d=Math.Abs(Math.Log((double)Math.Max(b[p]==0?256:b[p],b[p+1]==0?256:b[p+1])/size));if(d<score){best=p;score=d;}}return best;}
 static int FindChunk(byte[] b,string id){for(int p=12;p+8<=b.Length;){if(Encoding.ASCII.GetString(b,p,4)==id)return p;int n=BitConverter.ToInt32(b,p+4);p+=8+n+(n&1);}throw new Exception("Missing chunk "+id);}
}
public partial class MainForm {
 internal void TestSize(Skin s,int size,bool applyNow){s.SizeOverride=size;SizeTask=ResizeSkinAsync(s,applyNow);}
 internal void TestSizeCombo(Skin s,string value){SelectSkin(s);var combo=detail.Controls.OfType<DarkCombo>().Single();combo.SelectedItem=value;if(combo.SelectedItem==null)throw new Exception("Missing size choice");}
 internal void TestGlobalSize(int size){BeginInvoke(new MethodInvoker(()=>{var dialog=Application.OpenForms.OfType<SettingsDialog>().Single();dialog.Controls.OfType<DarkCombo>().Single().SelectedItem=size.ToString();dialog.Controls.OfType<Button>().Single(b=>b.Text=="保存设置").PerformClick();}));OpenSettings();}
}
